CREATE OR REPLACE FUNCTION public.whoami() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT jsonb_build_object('uid', auth.uid(), 'role', current_user, 'jwt_role', current_setting('request.jwt.claim.role', true), 'jwt_sub', current_setting('request.jwt.claim.sub', true), 'jwt_claims', current_setting('request.jwt.claims', true)) $$;
GRANT EXECUTE ON FUNCTION public.whoami() TO anon, authenticated, service_role;